// Shapes the AI SOAR webhook payload into a human-readable SOC alert.
// Every field below is emitted by src/ai_soar/orchestration/n8n.py::build_payload().
return items.map((item) => {
  const i = item.json.body || item.json;
  const cb = i.callback || {};
  const actions = (i.actions || []).map((a) => `${a.action} [${a.status}]`).join(', ') || 'none';
  return {
    json: {
      headline: `${String(i.severity || '').toUpperCase()} ${i.family} - ${i.incident_id}`,
      summary: `${i.family} detected (confidence ${i.confidence}, gate ${i.gate_probability}). Policy decision: ${i.decision}.`,
      incident_id: i.incident_id,
      family: i.family,
      severity: i.severity,
      needs_human: i.needs_human,
      pending_actions: (i.pending_actions || []).join(', ') || 'none',
      all_actions: actions,
      reason: i.decision_reason || '',
      detail_url: cb.detail || '',
      approve_url: cb.approve || '',
      dismiss_url: cb.dismiss || '',
      model_version: i.model_version || '',
      created_at: i.created_at || '',
      source: i.source || 'ai-soar',
    },
  };
});
